<script setup lang="ts">
import { ref,computed } from 'vue'
import type { Instrument,MarketProvider } from '../domain/types'
import type { StockDesk } from '../composables/useStockDesk'
import { number,percent,amount,trendClass } from '../domain/format'
import StockDetail from './StockDetail.vue'
import BaseDialog from './BaseDialog.vue'
import Icon from './Icon.vue'
const props=defineProps<{desk:StockDesk;provider:MarketProvider}>(),emit=defineEmits<{add:[groupId?:string];trade:[instrument:Instrument];alert:[instrument:Instrument];toast:[message:string]}>()
const group=ref('all'),filter=ref(''),sort=ref('manual'),direction=ref(-1),openMenu=ref<string|null>(null),groupDialog=ref(false),editingGroup=ref<string|null>(null),groupName=ref(''),groupError=ref('')
const data=computed(()=>props.desk.data.value),selected=computed(()=>data.value.instruments[props.desk.selectedSymbol.value])
const rows=computed(()=>data.value.watchlist.map((watch,index)=>({watch,index,stock:data.value.instruments[watch.symbol]!,quote:data.value.quoteCache[watch.symbol]})).filter(row=>(group.value==='all'||row.watch.groupId===group.value)&&(!filter.value||[row.stock.name,row.stock.code,row.stock.pinyin||''].some(v=>v.toLowerCase().includes(filter.value.toLowerCase())))).sort((a,b)=>{
 if(a.watch.pinned!==b.watch.pinned)return a.watch.pinned?-1:1
 if(sort.value==='manual')return a.index-b.index
 const av=sort.value==='name'?a.stock.name:sort.value==='price'?a.quote?.price:sort.value==='amount'?a.quote?.amount:a.quote?.changePercent
 const bv=sort.value==='name'?b.stock.name:sort.value==='price'?b.quote?.price:sort.value==='amount'?b.quote?.amount:b.quote?.changePercent
 if(av==null)return bv==null?0:1;if(bv==null)return -1
 return typeof av==='string'&&typeof bv==='string'?av.localeCompare(bv)*direction.value:(Number(av)-Number(bv))*direction.value
}))
const breadth=computed(()=>{const quoted=data.value.watchlist.map(w=>data.value.quoteCache[w.symbol]).filter(Boolean);return {up:quoted.filter(q=>q!.changePercent!=null&&q!.changePercent>0).length,down:quoted.filter(q=>q!.changePercent!=null&&q!.changePercent<0).length,flat:quoted.filter(q=>q!.changePercent===0).length,missing:data.value.watchlist.length-quoted.length}})
function changeSort(key:string){if(sort.value===key)direction.value*=-1;else{sort.value=key;direction.value=-1}}
function manageGroup(id?:string){editingGroup.value=id||null;groupName.value=id?data.value.groups.find(g=>g.id===id)?.name||'':'';groupError.value='';groupDialog.value=true}
function saveGroup(){try{if(editingGroup.value)props.desk.renameGroup(editingGroup.value,groupName.value);else group.value=props.desk.addGroup(groupName.value);groupDialog.value=false}catch(e){groupError.value=e instanceof Error?e.message:'分组保存失败'}}
function removeGroup(){try{props.desk.deleteGroup(editingGroup.value!);group.value='all';groupDialog.value=false}catch(e){groupError.value=e instanceof Error?e.message:'无法删除分组'}}
function removeWatch(symbol:string){props.desk.removeWatch(symbol);openMenu.value=null;emit('toast','已移出自选，持股及提醒记录保持不变')}
</script>
<template><div class="watchlist-layout">
 <section class="watchlist-panel surface"><div class="section-heading"><div><h2>自选盯盘 <span class="count-badge">{{data.watchlist.length}}</span></h2><p>关注行情变化，掌握自己的投资节奏</p></div><button class="button primary small" data-testid="add-stock" @click="emit('add',group==='all'?undefined:group)"><Icon name="plus" :size="16"/>添加股票</button></div>
  <div class="group-bar"><div class="group-tabs" aria-label="自选分组"><button :class="{active:group==='all'}" @click="group='all'">全部自选</button><button v-for="item in data.groups" :key="item.id" :class="{active:group===item.id}" @click="group=item.id" @dblclick="manageGroup(item.id)">{{item.name}}<span>{{data.watchlist.filter(w=>w.groupId===item.id).length}}</span></button></div><button class="icon-button" aria-label="新建自选分组" @click="manageGroup()"><Icon name="folder" :size="16"/></button><button v-if="group!=='all'" class="icon-button" aria-label="编辑当前分组" @click="manageGroup(group)"><Icon name="edit" :size="15"/></button></div>
  <div class="watchlist-filter"><label><Icon name="search" :size="15"/><input v-model="filter" aria-label="筛选自选股票" placeholder="筛选名称、代码…"/></label><select v-model="sort" aria-label="自选排序"><option value="manual">自定义排序</option><option value="change">按涨跌幅</option><option value="price">按现价</option><option value="amount">按成交额</option><option value="name">按名称</option></select></div>
  <div class="table-scroll"><table class="stock-table"><thead><tr><th class="stock-name-cell">股票名称 / 代码</th><th><button @click="changeSort('price')">现价<Icon v-if="sort==='price'" :name="direction<0?'arrowDown':'arrowUp'" :size="12"/></button></th><th><button @click="changeSort('change')">涨跌幅<Icon v-if="sort==='change'" :name="direction<0?'arrowDown':'arrowUp'" :size="12"/></button></th><th class="volume-cell"><button @click="changeSort('amount')">成交额</button></th><th class="actions-cell"/></tr></thead>
   <tbody><tr v-for="row in rows" :key="row.watch.symbol" :class="{selected:desk.selectedSymbol.value===row.watch.symbol}" @click="desk.select(row.watch.symbol)"><td class="stock-name-cell"><button class="stock-select" :aria-label="`查看 ${row.stock.name}`" @click.stop="desk.select(row.watch.symbol)"><span class="stock-title">{{row.stock.name}}<Icon v-if="row.watch.pinned" name="star" :size="12" class="pin-marker"/></span><span class="stock-code mono"><span class="market-prefix" :class="row.stock.market.toLowerCase()">{{row.stock.market==='CN'?row.stock.symbol.slice(0,2).toUpperCase():row.stock.market}}</span>{{row.stock.code}}</span></button></td><td class="mono quote-price" :class="trendClass(row.quote?.change)">{{number(row.quote?.price,row.stock.market==='HK'?3:2)}}<small v-if="desk.quoteState(row.stock.symbol)!=='fresh'">{{desk.quoteState(row.stock.symbol)==='unavailable'?'暂无':desk.quoteState(row.stock.symbol)==='error'?'旧行情':desk.quoteState(row.stock.symbol)==='cached'?'缓存':'快照'}}</small></td><td><span class="change-tag mono" :class="trendClass(row.quote?.changePercent)">{{percent(row.quote?.changePercent)}}</span></td><td class="mono muted volume-cell">{{amount(row.quote?.amount)}}</td><td class="actions-cell"><button class="icon-button compact" :aria-label="`${row.stock.name}操作`" :aria-expanded="openMenu===row.stock.symbol" @click.stop="openMenu=openMenu===row.stock.symbol?null:row.stock.symbol"><Icon name="dots" :size="17"/></button><div v-if="openMenu===row.stock.symbol" class="row-menu" @click.stop><button @click="desk.pinWatch(row.stock.symbol);openMenu=null"><Icon name="star" :size="14"/>{{row.watch.pinned?'取消置顶':'置顶股票'}}</button><button @click="emit('alert',row.stock);openMenu=null"><Icon name="bell" :size="14"/>设置提醒</button><button @click="desk.moveWatch(row.stock.symbol,-1);openMenu=null"><Icon name="arrowUp" :size="14"/>向上移动</button><button @click="desk.moveWatch(row.stock.symbol,1);openMenu=null"><Icon name="arrowDown" :size="14"/>向下移动</button><label>移到分组<select :value="row.watch.groupId" aria-label="移动股票到分组" @change="desk.moveToGroup(row.stock.symbol,($event.target as HTMLSelectElement).value);openMenu=null"><option v-for="g in data.groups" :key="g.id" :value="g.id">{{g.name}}</option></select></label><button class="danger" @click="removeWatch(row.stock.symbol)"><Icon name="trash" :size="14"/>移出自选</button></div></td></tr></tbody>
  </table><div v-if="!rows.length" class="empty-state"><Icon name="star" :size="34"/><h3>{{filter?'没有匹配的自选股票':'自选列表还是空的'}}</h3><p>添加关注的股票，行情会自动刷新</p><button class="button primary small" @click="emit('add',group==='all'?undefined:group)">添加股票</button></div></div>
  <div class="watchlist-footer"><span><i class="status-dot fresh"/>{{data.watchlist.length}} 只自选</span><div class="breadth"><span class="up">涨 {{breadth.up}}</span><span class="down">跌 {{breadth.down}}</span><span>平 {{breadth.flat}}</span><span v-if="breadth.missing">待更新 {{breadth.missing}}</span></div></div>
  <div class="watch-tip"><Icon name="info" :size="15"/>仅统计你的自选，不代表全市场；双击分组名称可编辑。</div>
 </section><StockDetail v-if="selected" :instrument="selected" :desk="desk" :provider="provider" @trade="emit('trade',$event)" @alert="emit('alert',$event)"/>
 <BaseDialog v-if="groupDialog" :title="editingGroup?'管理自选分组':'新建自选分组'" @close="groupDialog=false"><form class="dialog-form" @submit.prevent="saveGroup"><label class="form-label">分组名称<input v-model="groupName" maxlength="24" aria-label="分组名称" placeholder="如：长期持有、科技股" required/></label><p v-if="editingGroup" class="inline-notice">删除分组后，股票会移动到其他分组，不会删除股票。</p><p v-if="groupError" class="form-error" role="alert">{{groupError}}</p><div class="dialog-actions"><button v-if="editingGroup" type="button" class="button danger subtle" @click="removeGroup">删除分组</button><button type="button" class="button subtle" @click="groupDialog=false">取消</button><button type="submit" class="button primary">保存</button></div></form></BaseDialog>
</div></template>
